/**
 * Brand marks for the backing OSS tools. Each icon embeds the REAL official
 * upstream logo (fetched verbatim from the project's own artwork), centred on a
 * white rounded tile so both full-colour and single-colour marks stay legible
 * in light and dark mode. Full-colour logos are embedded as-is (their internal
 * ids/classes namespaced per icon to avoid cross-icon collisions when many
 * render at once); monochrome simple-icons marks are tinted with the brand hex.
 */

type BrandProps = { size?: number; className?: string }

function MonoTile({ size = 40, className, hex, d }: BrandProps & { hex: string; d: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" className={className} xmlns="http://www.w3.org/2000/svg" aria-hidden>
      <rect width="40" height="40" rx="9" fill="#ffffff" stroke="#e5e7eb" strokeWidth="0.5" />
      <svg x="7" y="7" width="26" height="26" viewBox="0 0 24 24">
        <g fill={hex}>
          <path d={d} />
        </g>
      </svg>
    </svg>
  )
}

function LogoTile({ size = 40, className, viewBox, markup }: BrandProps & { viewBox: string; markup: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" className={className} xmlns="http://www.w3.org/2000/svg" aria-hidden>
      <rect width="40" height="40" rx="9" fill="#ffffff" stroke="#e5e7eb" strokeWidth="0.5" />
      <svg x="7" y="7" width="26" height="26" viewBox={viewBox} dangerouslySetInnerHTML={{ __html: markup }} />
    </svg>
  )
}

